// Original R4 sample arithmetic/order preserved. Only invariant coordinates/guards and storage are cached.
export function createReusableAnimation(water,leaves,w,h){const pixels=new Uint8ClampedArray(w*h*4),xPhase=new Float64Array(w),yPhase=new Float64Array(h),rows=new Float64Array(h);for(let x=0;x<w;x++)xPhase[x]=x*.007;for(let y=0;y<h;y++)yPhase[y]=y*.031;
function cache(ids){const mask=new Uint8Array(w*h);for(const i of ids)mask[i]=1;const offsets=new Uint32Array(ids.length),xs=new Uint16Array(ids.length),ys=new Uint16Array(ids.length),guards=new Uint8Array(ids.length);for(let a=0;a<ids.length;a++){const i=ids[a],x=i%w,y=(i/w)|0;offsets[a]=i*4;xs[a]=x;ys[a]=y;guards[a]=(x>0&&mask[i-1]?1:0)|(x+1<w&&mask[i+1]?2:0)}return{offsets,xs,ys,guards}}
const wc=cache(water),lc=cache(leaves);
return function animate(source,t,{waterOn=true,leafOn=true}={}){pixels.set(source);let writes=0;function sample(cache,amp,period){const phase=t/period*Math.PI*2;for(let y=0;y<h;y++)rows[y]=phase+yPhase[y];const{offsets,xs,ys,guards}=cache;for(let a=0;a<offsets.length;a++){const shift=amp*Math.sin(rows[ys[a]]+xPhase[xs[a]]),left=shift<0;if(!(guards[a]&(left?1:2)))continue;const k=offsets[a],n=k+(left?-4:4),m=Math.abs(shift);pixels[k]=Math.round(source[k]*(1-m)+source[n]*m);pixels[k+1]=Math.round(source[k+1]*(1-m)+source[n+1]*m);pixels[k+2]=Math.round(source[k+2]*(1-m)+source[n+2]*m);writes++}}if(waterOn)sample(wc,.9,4200);if(leafOn)sample(lc,.55,3200);return{pixels,writes}}}
